      // the "migrated" mark only lasts while the task is still the one you sent to tomorrow: a new date, or a move elsewhere, clears it
      // (unless this very change is the one marking it)
      const marking = (patch.migratedOn !== undefined && patch.migratedOn !== i.migratedOn) || (patch.pulledOn !== undefined && patch.pulledOn !== i.pulledOn);
      if (!marking && (i.migratedOn || i.pulledOn) && (next.due !== i.due || next.someday || (next.status !== i.status && next.status !== "today"))) { next.migratedOn = null; next.pulledOn = null; }
